import json,math
NL=lambda k:(int(k[:-1]),'spdfg'.index(k[-1]))
import ground as G, nlchain as NC
sealed={d['Z']:d for d in map(json.loads,open('nlchain.jsonl'))}
cinf={d['Z']:d for d in map(json.loads,open('/tmp/cinf.jsonl'))}
clean=[];conf=[]
for Z in range(2,109):
    a=sorted(map(tuple,G.expand(Z-1))); b=sorted(map(tuple,NC.cfg_from_chain(Z-1,sealed)))
    (clean if a==b else conf).append(Z)
print('CLEAN steps (identical reference config):',len(clean),' CONFOUNDED:',len(conf))
dis=[Z for Z in clean if cinf[Z]['ent']!=sealed[Z]['ent']]
print('entrant differs on CLEAN subset:',dis)
# ordering + tiebreak restricted to clean
ov=[];viol=[];holds=0
for Z in clean:
    r=cinf[Z];e=tuple(r['ent_nl']);nl=sum(e);od=dict(r['order'])
    for k,v in od.items():
        if sum(NL(k))<nl and v>r['D_ent']: ov.append(Z)
    if any(NL(k)[0]+NL(k)[1]==nl and NL(k)[0]>e[0] for k in od): holds+=1
    for k,v in od.items():
        if NL(k)[0]+NL(k)[1]==nl and NL(k)[0]<e[0] and v>r['D_ent']: viol.append(Z)
print('CLEAN ordering failures:',sorted(set(ov)))
print('CLEAN tiebreak failures:',sorted(set(viol)),' exercised+obeyed',holds)
# same on sealed over clean subset for reconciliation
ov2=[];viol2=[]
for Z in clean:
    r=sealed[Z];e=tuple(r['ent_nl']);nl=sum(e);od=dict(r['order'])
    for k,v in od.items():
        if sum(NL(k))<nl and v>r['D_ent']: ov2.append(Z)
        if NL(k)[0]+NL(k)[1]==nl and NL(k)[0]<e[0] and v>r['D_ent']: viol2.append(Z)
print('SEALED same subset ordering:',sorted(set(ov2)),' tiebreak:',sorted(set(viol2)))
# NR-3 on clean subset
agg={}
for Z in clean:
    a=dict(sealed[Z]['order']);b=dict(cinf[Z]['order'])
    sh=[abs(a[k]-b[k]) for k in a if k in b and not k.endswith('g')]
    if sh: agg[Z]=max(sh)
lo=[agg[Z] for Z in agg if Z<30]
zmax=max(agg,key=lambda z:agg[z])
print('NR-3 clean: max|dD| Z<30 = %.6f Ha  (n=%d)'%(max(lo),len(lo)))
print('NR-3 clean: largest %.4f Ha at Z=%d'%(agg[zmax],zmax))
print('NR-3 clean: max over Z in 30..80 = %.4f'%max(agg[Z] for Z in agg if 30<=Z<=80))
gm=0
for Z in clean:
    a=dict(sealed[Z]['order']);b=dict(cinf[Z]['order'])
    for k in a:
        if k.endswith('g') and k in b: gm=max(gm,abs(a[k]-b[k]))
print('NR-5 clean: max g shift %.2e'%gm)
okc=sum(1 for Z in clean if cinf[Z]['ok']); oks=sum(1 for Z in clean if sealed[Z]['ok'])
print('ok on clean subset: c=1e6 %d/%d   sealed %d/%d'%(okc,len(clean),oks,len(clean)))
"

